const D = { density:.5, scale:1, energy:.6, speed:1, hue:200, x:.5, y:.5, seed:0, style:'moire', act:'orbit' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const TAU = 6.28318530718, cl = (v,a,b)=>v<a?a:v>b?b:v;
const fr = i=>{ const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };

// ---- working buffer keyed on aspect bucket ----
const asp = width/height;
const LS = 190;
let bw, bh;
if (asp>=1){ bw=LS; bh=Math.max(8,Math.round(LS/asp)); } else { bh=LS; bw=Math.max(8,Math.round(LS*asp)); }
const bkey = bw+'x'+bh;
if (!S.buf || S.bkey!==bkey){ if (S.buf && S.buf.remove) S.buf.remove(); S.buf = createGraphics(bw,bh); S.buf.pixelDensity(1); S.bkey = bkey; }
const g = S.buf;

// ---- seeded wave sources ----
const nS = 2 + Math.round(cl(P.density,0,1)*2);
if (S.seedUsed!==P.seed || S.nS!==nS){
  S.seedUsed = P.seed; S.nS = nS;
  const src = [];
  for (let i=0;i<nS;i++){
    src.push({
      ang: fr(i*7)*TAU,
      rad: .08 + fr(i*7+1)*.20,
      orb: (.25 + fr(i*7+2)*.6) * (fr(i*7+6)<.5?-1:1),
      ph:  fr(i*7+3)*TAU,
      phR: (.6 + fr(i*7+4)*1.4) * (fr(i*7+7)<.5?-1:1),
      w:   .7 + fr(i*7+5)*.6
    });
  }
  S.src = src;
}

// ---- color LUT keyed on style+hue ----
const lkey = P.style+'|'+Math.round(P.hue);
if (S.lkey!==lkey){
  S.lkey = lkey; const N=128;
  const R=new Uint8Array(N), Gc=new Uint8Array(N), B=new Uint8Array(N);
  for (let i=0;i<N;i++){
    const t=i/(N-1); let h,s,b;
    if (P.style==='thermal'){ h=(270*(1-cl(t,0,1)))%360; s = t>.85 ? 90-(t-.85)/.15*70 : 90; b = 15+80*t; }
    else if (P.style==='blueprint'){ if (t<.8){ h=215; s=72; b=14+t*8; } else { const bt=(t-.8)/.2; h=200; s=80-45*bt; b=28+66*bt; } }
    else if (P.style==='plasma'){ h=(P.hue+t*300)%360; s=68; b=42+34*Math.sin(t*TAU); }
    else if (P.style==='duotone'){ h = t<.5 ? P.hue : (P.hue+165)%360; s=62; b=22+66*t; }
    else { const tt=Math.pow(t,.85); h=(P.hue+t*24)%360; s=60-25*tt; b=8+88*tt; }
    const c=color(h,s,b); R[i]=c.levels[0]; Gc[i]=c.levels[1]; B[i]=c.levels[2];
  }
  S.R=R; S.Gc=Gc; S.B=B;
}

// ---- per-frame source positions ----
const spd = cl(P.speed,.2,4), en = cl(P.energy,0,1);
const sec = .5 + .5*Math.sin(K.section/8*TAU + K.t*.03);
const freqBase = (2.5 + cl(P.density,0,1)*4) * cl(P.scale,.3,3) * (1 + .12*K.swell + .15*(A.treble||0));
const src = S.src;
const SX=new Float32Array(nS), SY=new Float32Array(nS), PH=new Float32Array(nS), WT=new Float32Array(nS);
let radMod=1, rot=0;
if (P.act==='pulse'){ radMod = .6 + .7*sec; }
else if (P.act==='converge'){ radMod = .35 + .65*(.5+.5*Math.sin(K.t*.05*spd)); rot = K.t*.1*spd; }
for (let i=0;i<nS;i++){
  const s=src[i];
  const a = s.ang + K.t*spd*s.orb*.25 + rot;
  const r = s.rad*radMod*(1 + .25*Math.sin(K.t*.07*spd + i));
  SX[i] = cl(P.x,0,1) + Math.cos(a)*r;
  SY[i] = cl(P.y,0,1) + Math.sin(a)*r;
  PH[i] = s.ph + K.t*spd*s.phR + K.pulse*.5*i;
  WT[i] = s.w;
}

// ---- render field ----
g.loadPixels();
const px = g.pixels, invW = 1/(bw-1), invH = 1/(bh-1);
const cN=127, R=S.R, Gc=S.Gc, B=S.B, invNs=1/nS;
const contrast = .6 + en*1.2;
const levels = P.style==='duotone' ? 5 : 0;
let idx=0;
for (let yy=0; yy<bh; yy++){
  const ny = yy*invH;
  for (let xx=0; xx<bw; xx++){
    const nx = xx*invW;
    let s=0;
    for (let i=0;i<nS;i++){
      const dx=(nx-SX[i])*asp, dy=ny-SY[i];
      const d=Math.sqrt(dx*dx+dy*dy);
      s += Math.cos(d*freqBase*TAU - PH[i])*WT[i];
    }
    let u = (s*invNs)*.5 + .5;
    u = .5 + (u-.5)*contrast;
    if (u<0) u=0; else if (u>1) u=1;
    if (levels) u = Math.floor(u*levels)/(levels-1);
    let li = (u*cN)|0; if (li<0) li=0; else if (li>cN) li=cN;
    px[idx]=R[li]; px[idx+1]=Gc[li]; px[idx+2]=B[li]; px[idx+3]=255; idx+=4;
  }
}
g.updatePixels();

drawingContext.imageSmoothingEnabled = true;
image(g,0,0,width,height);
blendMode(BLEND);
